import type { WikiPage } from './wiki.js';

// CJK Unicode ranges for bigram tokenization
const CJK_RE = /[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff\u3000-\u303f\u3040-\u309f\u30a0-\u30ff\uac00-\ud7af]/;

export function tokenize(text: string): string[] {
  const tokens: string[] = [];
  const normalized = text.toLowerCase();

  // Split into segments: CJK vs non-CJK
  let i = 0;
  let nonCjkBuffer = '';

  while (i < normalized.length) {
    const char = normalized[i];
    if (CJK_RE.test(char)) {
      // Flush non-CJK buffer
      if (nonCjkBuffer.length > 0) {
        tokens.push(...nonCjkBuffer.split(/\s+/).filter(t => t.length > 0));
        nonCjkBuffer = '';
      }
      // CJK bigram: emit single char + bigram with next CJK char
      tokens.push(char);
      if (i + 1 < normalized.length && CJK_RE.test(normalized[i + 1])) {
        tokens.push(char + normalized[i + 1]);
      }
      i++;
    } else {
      nonCjkBuffer += char;
      i++;
    }
  }
  if (nonCjkBuffer.length > 0) {
    tokens.push(...nonCjkBuffer.split(/\s+/).filter(t => t.length > 0));
  }

  return tokens;
}

interface BM25Index {
  /** Document frequency: token → number of docs containing it */
  df: Map<string, number>;
  /** Term frequency per doc: docIndex → token → count */
  tf: Map<number, Map<string, number>>;
  /** Document lengths (in tokens) */
  docLengths: number[];
  /** Average document length */
  avgDl: number;
  /** Total documents */
  n: number;
}

function buildIndex(pages: WikiPage[]): BM25Index {
  const df = new Map<string, number>();
  const tf = new Map<number, Map<string, number>>();
  const docLengths: number[] = [];

  for (let i = 0; i < pages.length; i++) {
    const page = pages[i];
    const text = `${page.title} ${page.description ?? ''} ${page.content}`;
    const tokens = tokenize(text);
    docLengths.push(tokens.length);

    const termFreq = new Map<string, number>();
    const seenTerms = new Set<string>();

    for (const token of tokens) {
      termFreq.set(token, (termFreq.get(token) ?? 0) + 1);
      seenTerms.add(token);
    }

    tf.set(i, termFreq);
    for (const term of seenTerms) {
      df.set(term, (df.get(term) ?? 0) + 1);
    }
  }

  const totalLen = docLengths.reduce((a, b) => a + b, 0);
  const avgDl = pages.length > 0 ? totalLen / pages.length : 0;

  return { df, tf, docLengths, avgDl, n: pages.length };
}

const K1 = 1.2;
const B = 0.75;

function scoreBM25(index: BM25Index, queryTokens: string[], docIdx: number): number {
  let score = 0;
  const docTf = index.tf.get(docIdx);
  if (!docTf) return 0;
  const dl = index.docLengths[docIdx];

  for (const token of queryTokens) {
    const docFreq = index.df.get(token) ?? 0;
    if (docFreq === 0) continue;

    const idf = Math.log((index.n - docFreq + 0.5) / (docFreq + 0.5) + 1);
    const termFreq = docTf.get(token) ?? 0;
    const tfNorm = (termFreq * (K1 + 1)) / (termFreq + K1 * (1 - B + B * dl / index.avgDl));
    score += idf * tfNorm;
  }

  return score;
}

export interface SearchResult {
  page: WikiPage;
  score: number;
}

export function bm25Search(pages: WikiPage[], query: string, limit: number = 10): SearchResult[] {
  if (pages.length === 0) return [];

  const index = buildIndex(pages);
  const queryTokens = tokenize(query);

  const results: SearchResult[] = [];
  for (let i = 0; i < pages.length; i++) {
    const score = scoreBM25(index, queryTokens, i);
    if (score > 0) {
      results.push({ page: pages[i], score });
    }
  }

  results.sort((a, b) => b.score - a.score);
  return results.slice(0, limit);
}

/**
 * Reciprocal Rank Fusion (RRF) — merges ranked lists from different search methods.
 * K=60 is the standard constant.
 */
export function rrfMerge(
  bm25Results: { slug: string; score: number }[],
  vectorResults: { slug: string; score: number }[],
  limit: number,
  k: number = 60
): { slug: string; score: number }[] {
  const scores = new Map<string, number>();

  for (let i = 0; i < bm25Results.length; i++) {
    const slug = bm25Results[i].slug;
    scores.set(slug, (scores.get(slug) ?? 0) + 1 / (k + i + 1));
  }

  for (let i = 0; i < vectorResults.length; i++) {
    const slug = vectorResults[i].slug;
    scores.set(slug, (scores.get(slug) ?? 0) + 1 / (k + i + 1));
  }

  return [...scores.entries()]
    .map(([slug, score]) => ({ slug, score }))
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}

import { Command } from 'commander';
import { requireVaultRoot, vaultPaths, loadConfig } from '../lib/config.js';
import { loadWikiPages } from '../lib/wiki.js';
import { bm25Search, rrfMerge } from '../lib/search.js';
import { createDB9Client } from '../lib/db9.js';

export const searchCommand = new Command('search')
  .description('Search wiki pages (BM25 + DB9 vector search if configured)')
  .argument('<query>', 'search query')
  .option('-n, --limit <number>', 'max results', '10')
  .option('--bm25-only', 'force BM25-only search even if DB9 is configured')
  .action(async (query: string, opts: { limit: string; bm25Only?: boolean }) => {
    const root = requireVaultRoot();
    const paths = vaultPaths(root);
    const config = loadConfig(root);
    const pages = loadWikiPages(paths.wiki);

    if (pages.length === 0) {
      console.log('No wiki pages found. Use /ingest to add content.');
      return;
    }

    const limit = parseInt(opts.limit, 10);
    const pagesBySlug = new Map(pages.map(p => [p.slug, p]));

    // BM25 search
    const bm25Results = bm25Search(pages, query, limit * 2);

    // Try DB9 vector search if configured
    const db9 = !opts.bm25Only ? createDB9Client(config) : null;
    let vectorResults: { slug: string; score: number }[] = [];
    let hybridMode = false;

    if (db9) {
      try {
        const dbResults = await db9.vectorSearch(query, limit * 2);
        vectorResults = dbResults.map(r => ({ slug: r.slug, score: r.similarity }));
        hybridMode = vectorResults.length > 0;
      } catch (err) {
        console.error(`DB9 search failed, falling back to BM25: ${err instanceof Error ? err.message : err}`);
      } finally {
        await db9.close();
      }
    }

    let finalResults: { slug: string; score: number }[];

    if (hybridMode) {
      // RRF merge of BM25 + vector results
      finalResults = rrfMerge(
        bm25Results.map(r => ({ slug: r.page.slug, score: r.score })),
        vectorResults,
        limit
      );
      console.log(`Results for "${query}" (hybrid BM25 + vector, ${finalResults.length} matches):\n`);
    } else {
      finalResults = bm25Results.slice(0, limit).map(r => ({ slug: r.page.slug, score: r.score }));
      console.log(`Results for "${query}" (BM25, ${finalResults.length} matches):\n`);
    }

    if (finalResults.length === 0) {
      console.log(`No results for "${query}"`);
      return;
    }

    for (const { slug, score } of finalResults) {
      const page = pagesBySlug.get(slug);
      console.log(`  ${slug}`);
      if (page) {
        console.log(`    Title: ${page.title}`);
        if (page.description) console.log(`    ${page.description}`);
        console.log(`    Score: ${score.toFixed(4)} | Tags: ${page.tags.join(', ') || 'none'}`);
      }
      console.log('');
    }
  });

