import { describe, it, expect } from 'vitest';
import { rrfMerge } from '../src/lib/search.js';

describe('RRF merge', () => {
  it('should boost pages that appear in both lists', () => {
    const bm25 = [
      { slug: 'a', score: 5 },
      { slug: 'b', score: 3 },
    ];
    const vector = [
      { slug: 'b', score: 0.9 },
      { slug: 'c', score: 0.8 },
    ];
    const result = rrfMerge(bm25, vector, 10);
    // 'b' appears in both lists, should rank highest
    expect(result[0].slug).toBe('b');
  });

  it('should respect limit', () => {
    const bm25 = [
      { slug: 'a', score: 5 },
      { slug: 'b', score: 3 },
      { slug: 'c', score: 1 },
    ];
    const vector = [
      { slug: 'd', score: 0.9 },
      { slug: 'e', score: 0.8 },
    ];
    const result = rrfMerge(bm25, vector, 3);
    expect(result.length).toBe(3);
  });

  it('should handle empty inputs', () => {
    expect(rrfMerge([], [], 10)).toEqual([]);
    expect(rrfMerge([{ slug: 'a', score: 1 }], [], 10).length).toBe(1);
    expect(rrfMerge([], [{ slug: 'a', score: 1 }], 10).length).toBe(1);
  });

  it('should maintain scores relative to rank position', () => {
    const bm25 = [
      { slug: 'a', score: 10 },
      { slug: 'b', score: 5 },
    ];
    const vector: { slug: string; score: number }[] = [];
    const result = rrfMerge(bm25, vector, 10);
    expect(result[0].slug).toBe('a');
    expect(result[0].score).toBeGreaterThan(result[1].score);
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { execSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync, rmSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const CLI = join(import.meta.dirname, '..', 'dist', 'cli.js');
let testDir: string;

beforeEach(() => {
  testDir = join(tmpdir(), `llm-wiki-init-${Date.now()}`);
  mkdirSync(testDir, { recursive: true });
});

afterEach(() => {
  rmSync(testDir, { recursive: true, force: true });
});

describe('init command', () => {
  it('should create vault structure', () => {
    execSync(`node ${CLI} init`, { cwd: testDir });
    expect(existsSync(join(testDir, 'wiki'))).toBe(true);
    expect(existsSync(join(testDir, 'sources'))).toBe(true);
    expect(existsSync(join(testDir, 'wiki-purpose.md'))).toBe(true);
    expect(existsSync(join(testDir, 'wiki-schema.md'))).toBe(true);
    expect(existsSync(join(testDir, 'wiki-log.md'))).toBe(true);
    expect(existsSync(join(testDir, '.llm-wiki/config.toml'))).toBe(true);
    // v0.4.2 rename: old unprefixed names must not be created
    expect(existsSync(join(testDir, 'purpose.md'))).toBe(false);
    expect(existsSync(join(testDir, 'schema.md'))).toBe(false);
    expect(existsSync(join(testDir, 'log.md'))).toBe(false);
  });

  it('should generate agent bootstrap files', () => {
    execSync(`node ${CLI} init`, { cwd: testDir });
    expect(existsSync(join(testDir, 'CLAUDE.md'))).toBe(true);
    expect(existsSync(join(testDir, 'AGENTS.md'))).toBe(true);
  });

  it('should auto-install skills to both agent dirs in spec-compliant layout', () => {
    execSync(`node ${CLI} init`, { cwd: testDir });
    const skills = ['ingest', 'query', 'lint', 'research'];
    for (const name of skills) {
      const claudeSkill = join(testDir, '.claude/skills', name, 'SKILL.md');
      const agentsSkill = join(testDir, '.agents/skills', name, 'SKILL.md');
      expect(existsSync(claudeSkill)).toBe(true);
      expect(existsSync(agentsSkill)).toBe(true);

      // Content must match (not just empty files) and must include Agent Skills
      // frontmatter so any compliant agent can independently discover it.
      const claudeContent = readFileSync(claudeSkill, 'utf-8');
      const agentsContent = readFileSync(agentsSkill, 'utf-8');
      expect(claudeContent.length).toBeGreaterThan(100);
      expect(claudeContent).toEqual(agentsContent);
      expect(claudeContent.startsWith('---\n')).toBe(true);
      expect(claudeContent).toMatch(new RegExp(`\\nname:\\s*${name}\\b`));
      expect(claudeContent).toMatch(/\ndescription:\s*\S/);
    }
    expect(existsSync(join(testDir, '.claude/skills/llm-wiki/SKILL.md'))).toBe(false);
    expect(existsSync(join(testDir, '.agents/skills/llm-wiki/SKILL.md'))).toBe(false);
  });

  it('should not clobber pre-existing customized skill files', () => {
    const claudeSkillDir = join(testDir, '.claude/skills/ingest');
    mkdirSync(claudeSkillDir, { recursive: true });
    const customContent = '---\nname: ingest\ndescription: custom\n---\n\n# My Custom Skill\n\nDo not overwrite me.\n';
    writeFileSync(join(claudeSkillDir, 'SKILL.md'), customContent);

    execSync(`node ${CLI} init`, { cwd: testDir });

    expect(readFileSync(join(claudeSkillDir, 'SKILL.md'), 'utf-8')).toEqual(customContent);
    // Fresh dir still gets the bundled skill
    expect(existsSync(join(testDir, '.agents/skills/ingest/SKILL.md'))).toBe(true);
    expect(existsSync(join(testDir, '.agents/skills/query/SKILL.md'))).toBe(true);
  });

  it('should not overwrite existing files', () => {
    execSync(`node ${CLI} init`, { cwd: testDir });
    // Should fail if already initialized
    expect(() => execSync(`node ${CLI} init`, { cwd: testDir, stdio: 'pipe' })).toThrow();
  });

  it('should initialize an absolute target path without nesting it under cwd', () => {
    const targetDir = join(testDir, 'absolute-vault');
    execSync(`node ${CLI} init ${targetDir}`, { cwd: testDir });

    expect(existsSync(join(targetDir, '.llm-wiki/config.toml'))).toBe(true);
    expect(existsSync(join(testDir, targetDir.replace(/^\//, '')))).toBe(false);
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { computeSync, updateSyncState } from '../src/lib/sync.js';
import type { SyncState } from '../src/lib/sync.js';

let testDir: string;

beforeEach(() => {
  testDir = join(tmpdir(), `llm-wiki-test-${Date.now()}`);
  mkdirSync(join(testDir, 'wiki'), { recursive: true });
});

afterEach(() => {
  rmSync(testDir, { recursive: true, force: true });
});

describe('computeSync', () => {
  it('should detect added files', () => {
    writeFileSync(join(testDir, 'wiki/page-a.md'), '# Page A');
    const emptyState: SyncState = { entries: {}, lastSync: '' };
    const result = computeSync([join(testDir, 'wiki')], testDir, emptyState);
    expect(result.added).toEqual(['wiki/page-a.md']);
    expect(result.modified).toEqual([]);
    expect(result.deleted).toEqual([]);
  });

  it('should detect deleted files', () => {
    const state: SyncState = {
      entries: {
        'wiki/deleted.md': { path: 'wiki/deleted.md', mtime: 0, contentHash: 'abc', lastSynced: '2026-01-01' },
      },
      lastSync: '2026-01-01',
    };
    const result = computeSync([join(testDir, 'wiki')], testDir, state);
    expect(result.deleted).toEqual(['wiki/deleted.md']);
  });

  it('should detect unchanged files', () => {
    const filePath = join(testDir, 'wiki/page.md');
    writeFileSync(filePath, '# Unchanged');
    const state = updateSyncState([join(testDir, 'wiki')], testDir, { entries: {}, lastSync: '' });
    const result = computeSync([join(testDir, 'wiki')], testDir, state);
    expect(result.unchanged).toEqual(['wiki/page.md']);
  });
});

describe('updateSyncState', () => {
  it('should create entries for all files', () => {
    writeFileSync(join(testDir, 'wiki/a.md'), '# A');
    writeFileSync(join(testDir, 'wiki/b.md'), '# B');
    const state = updateSyncState([join(testDir, 'wiki')], testDir, { entries: {}, lastSync: '' });
    expect(Object.keys(state.entries)).toHaveLength(2);
    expect(state.entries['wiki/a.md']).toBeDefined();
    expect(state.entries['wiki/b.md']).toBeDefined();
    expect(state.entries['wiki/a.md'].contentHash).toBeTruthy();
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { DB9Client } from '../src/lib/db9.js';
import type { WikiPage } from '../src/lib/wiki.js';

const DB9_URL = process.env.DB9_URL;

// Skip all DB9 tests if no connection string is set
const describeDB9 = DB9_URL ? describe : describe.skip;

function makePage(slug: string, title: string, content: string): WikiPage {
  return {
    path: `wiki/${slug}.md`,
    relativePath: `${slug}.md`,
    slug,
    title,
    description: `About ${title}`,
    content,
    tags: ['test'],
    sources: ['2026-04-19/test-source.md'],
    aliases: [],
    wikilinks: [],
    mtime: Date.now(),
    updated: '2026-04-19',
  };
}

describeDB9('DB9 integration', () => {
  let client: DB9Client;

  beforeAll(async () => {
    client = new DB9Client({ url: DB9_URL! });
    await client.ensureSchema();
  });

  afterAll(async () => {
    await client.close();
  });

  it('should upsert and retrieve a page hash', async () => {
    const page = makePage('test-page', 'Test Page', 'This is a test page about distributed systems.');
    await client.upsertPage(page, 'abc123');

    const hash = await client.getContentHash('test-page');
    expect(hash).toBe('abc123');
  });

  it('should update a page on upsert', async () => {
    const page = makePage('test-page', 'Test Page Updated', 'Updated content.');
    await client.upsertPage(page, 'def456');

    const hash = await client.getContentHash('test-page');
    expect(hash).toBe('def456');
  });

  it('should vector search', async () => {
    // Insert a few pages with different topics
    await client.upsertPage(
      makePage('consensus', 'Consensus', 'Distributed consensus algorithms like Raft and Paxos.'),
      'hash1'
    );
    await client.upsertPage(
      makePage('cooking', 'Cooking', 'How to make pasta carbonara with eggs and bacon.'),
      'hash2'
    );

    const results = await client.vectorSearch('distributed systems agreement protocol', 5);
    expect(results.length).toBeGreaterThan(0);
    // Consensus should rank higher than cooking for this query
    const consensusIdx = results.findIndex(r => r.slug === 'consensus');
    const cookingIdx = results.findIndex(r => r.slug === 'cooking');
    if (consensusIdx >= 0 && cookingIdx >= 0) {
      expect(consensusIdx).toBeLessThan(cookingIdx);
    }
  });

  it('should get all hashes', async () => {
    const hashes = await client.getAllHashes();
    expect(hashes.size).toBeGreaterThanOrEqual(2);
    expect(hashes.has('consensus')).toBe(true);
  });

  it('should track page-source mappings', async () => {
    const pages = await client.pagesBySource('2026-04-19/test-source.md');
    expect(pages.length).toBeGreaterThan(0);
  });

  it('should delete a page', async () => {
    await client.deletePage('cooking');
    const hash = await client.getContentHash('cooking');
