export const statusCommand = new Command('status')
  .description('Show wiki statistics and health summary')
  .action(() => {
    const root = requireVaultRoot();
    const paths = vaultPaths(root);
    const config = loadConfig(root);

    // Count pages
    const pages = loadWikiPages(paths.wiki);
    const sourceFiles = listMarkdownFiles(paths.sources);

    // Check sync state
    const syncState = loadSyncState(paths.syncState);

    // Count log entries
    let logEntries = 0;
    let lastLogEntry = '';
    if (existsSync(paths.log)) {
      const logContent = readFileSync(paths.log, 'utf-8');
      const logLines = logContent.match(/^## \[/gm);
      logEntries = logLines?.length ?? 0;
      const lastMatch = logContent.match(/^## \[[\d-]+\].+$/gm);
      if (lastMatch) lastLogEntry = lastMatch[lastMatch.length - 1];
    }

    // Health checks
    const issues: string[] = [];
    const legacyRename: [string, string][] = [
      ['purpose.md', 'wiki-purpose.md'],
      ['schema.md', 'wiki-schema.md'],
      ['log.md', 'wiki-log.md'],
    ];
    for (const [oldName, newName] of legacyRename) {
      if (!existsSync(join(root, newName)) && existsSync(join(root, oldName))) {
        issues.push(`legacy ${oldName} detected — rename to ${newName} (v0.4.2 vault file rename)`);
      }
    }
    if (!existsSync(paths.purpose)) issues.push('wiki-purpose.md missing');
    if (!existsSync(paths.schema)) issues.push('wiki-schema.md missing');

    const pagesWithoutSources = pages.filter(p => p.sources.length === 0);
    if (pagesWithoutSources.length > 0) {
      issues.push(`${pagesWithoutSources.length} pages without sources`);
    }

    // Find broken wikilinks
    const slugSet = new Set(pages.map(p => p.slug.toLowerCase()));
    let brokenLinks = 0;
    for (const page of pages) {
      for (const link of page.wikilinks) {
        if (!slugSet.has(link.toLowerCase().replace(/\.md$/, ''))) {
          brokenLinks++;
        }
      }
    }
    if (brokenLinks > 0) issues.push(`${brokenLinks} broken wikilinks`);

    // Recent pages (last 5 modified)
    const recentPages = [...pages]
      .sort((a, b) => b.mtime - a.mtime)
      .slice(0, 5);

    // Output
    console.log(`Wiki: ${config.vault.name}`);
    console.log(`Language: ${config.vault.language}`);
    console.log('');
    console.log(`Pages:   ${pages.length}`);
    console.log(`Sources: ${sourceFiles.length}`);
    console.log(`Links:   ${pages.reduce((sum, p) => sum + p.wikilinks.length, 0)}`);
    console.log(`Log:     ${logEntries} entries`);
    if (syncState.lastSync) {
      console.log(`Synced:  ${syncState.lastSync}`);
    }
    console.log('');

    if (recentPages.length > 0) {
      console.log('Recently Modified:');
      for (const page of recentPages) {
        const date = new Date(page.mtime).toISOString().slice(0, 10);
        console.log(`  ${date} — [[${page.slug}]]`);
      }
      console.log('');
    }

    if (issues.length > 0) {
      console.log('Health Issues:');
      for (const issue of issues) {
        console.log(`  ⚠ ${issue}`);
      }
      console.log('');
      console.log('Run `llm-wiki graph` for detailed analysis or `/lint` for a full health check.');
    } else {
      console.log('Health: OK');
    }
  });

import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync, statSync } from 'node:fs';
import { relative } from 'node:path';
import { listMarkdownFiles } from './wiki.js';

export interface SyncEntry {
  path: string;
  mtime: number;
  contentHash: string;
  lastSynced: string;
}

export interface SyncState {
  entries: Record<string, SyncEntry>;
  lastSync: string;
}

export function loadSyncState(statePath: string): SyncState {
  if (!existsSync(statePath)) {
    return { entries: {}, lastSync: '' };
  }
  return JSON.parse(readFileSync(statePath, 'utf-8'));
}

export function saveSyncState(statePath: string, state: SyncState): void {
  writeFileSync(statePath, JSON.stringify(state, null, 2));
}

export function contentHash(filePath: string): string {
  const content = readFileSync(filePath, 'utf-8');
  return createHash('sha256').update(content).digest('hex').slice(0, 16);
}

export interface SyncResult {
  added: string[];
  modified: string[];
  deleted: string[];
  unchanged: string[];
}

/**
 * Compare current wiki/sources state against saved sync state.
 * Returns lists of changed files.
 */
export function computeSync(
  dirs: string[],
  baseDir: string,
  state: SyncState
): SyncResult {
  const result: SyncResult = { added: [], modified: [], deleted: [], unchanged: [] };
  const currentFiles = new Set<string>();

  for (const dir of dirs) {
    for (const filePath of listMarkdownFiles(dir)) {
      const rel = relative(baseDir, filePath);
      currentFiles.add(rel);
      const stat = statSync(filePath);
      const existing = state.entries[rel];

      if (!existing) {
        result.added.push(rel);
      } else if (stat.mtimeMs !== existing.mtime) {
        // mtime changed, check content hash
        const hash = contentHash(filePath);
        if (hash !== existing.contentHash) {
          result.modified.push(rel);
        } else {
          result.unchanged.push(rel);
        }
      } else {
        result.unchanged.push(rel);
      }
    }
  }

  // Check for deleted files
  for (const rel of Object.keys(state.entries)) {
    if (!currentFiles.has(rel)) {
      result.deleted.push(rel);
    }
  }

  return result;
}

/**
 * Update sync state with current file metadata.
 */
export function updateSyncState(
  dirs: string[],
  baseDir: string,
  state: SyncState
): SyncState {
  const newEntries: Record<string, SyncEntry> = {};
  const now = new Date().toISOString().slice(0, 10);

  for (const dir of dirs) {
    for (const filePath of listMarkdownFiles(dir)) {
      const rel = relative(baseDir, filePath);
      const stat = statSync(filePath);
      newEntries[rel] = {
        path: rel,
        mtime: stat.mtimeMs,
        contentHash: contentHash(filePath),
        lastSynced: now,
      };
    }
  }

  return { entries: newEntries, lastSync: now };
}

import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import TOML from 'toml';

export interface WikiConfig {
  vault: {
    name: string;
    language: string;
  };
  db9?: {
    url: string;
  };
}

const DEFAULT_CONFIG: WikiConfig = {
  vault: {
    name: 'My Wiki',
    language: 'en',
  },
};

const CONFIG_PATH = '.llm-wiki/config.toml';

export function findVaultRoot(from: string = process.cwd()): string | null {
  let dir = resolve(from);
  while (true) {
    if (existsSync(join(dir, CONFIG_PATH))) {
      return dir;
    }
    const parent = resolve(dir, '..');
    if (parent === dir) return null;
    dir = parent;
  }
}

export function requireVaultRoot(from?: string): string {
  const root = findVaultRoot(from);
  if (!root) {
    console.error('Error: Not inside an llm-wiki vault. Run `llm-wiki init` first.');
    process.exit(1);
  }
  return root;
}

export function loadConfig(vaultRoot: string): WikiConfig {
  const configPath = join(vaultRoot, CONFIG_PATH);
  if (!existsSync(configPath)) return DEFAULT_CONFIG;
  const raw = readFileSync(configPath, 'utf-8');
  return { ...DEFAULT_CONFIG, ...TOML.parse(raw) } as WikiConfig;
}

export function vaultPaths(root: string) {
  return {
    wiki: join(root, 'wiki'),
    sources: join(root, 'sources'),
    purpose: join(root, 'wiki-purpose.md'),
    schema: join(root, 'wiki-schema.md'),
    agent: join(root, 'wiki-agent.md'),
    log: join(root, 'wiki-log.md'),
    claudeMd: join(root, 'CLAUDE.md'),
    agentsMd: join(root, 'AGENTS.md'),
    claudeSkillsDir: join(root, '.claude', 'skills'),
    agentsSkillsDir: join(root, '.agents', 'skills'),
    config: join(root, CONFIG_PATH),
    syncState: join(root, '.llm-wiki/sync-state.json'),
    lintResult: join(root, '.llm-wiki/lint-result.yaml'),
    llmWikiDir: join(root, '.llm-wiki'),
  };
}

